function Analysis({patient,single,imageSource,imageData,availableEyes,onDone}:{patient:Patient;single:boolean;imageSource:string;imageData:Case['imageData'];availableEyes:string[];onDone:(result:AIAnalysisResult)=>void}){const [stage,setStage]=useState(0),[busy,setBusy]=useState(false),[error,setError]=useState(''),[attempt,setAttempt]=useState(0);const stages=['QUALITY TRIAGE','DETERMINISTIC ENHANCEMENT','LESION SEGMENTATION','CLINICAL SPATIAL FEATURES','HYBRID CNN + SYMBOLIC GRADING','EXPLAINABILITY','CONFORMAL TRIAGE'];useEffect(()=>{let cancelled=false;const ids:number[]=[];stages.forEach((_,i)=>ids.push(window.setTimeout(()=>setStage(i+1),1700*(i+1))));ids.push(window.setTimeout(async()=>{setStage(stages.length);setBusy(true);try{const result=await analyzeRetinalCase({patientId:patient.id,rightImage:imageData?.right,leftImage:imageData?.left,availableEyes});if(!cancelled)onDone(result)}catch{if(!cancelled){setError('Demo analysis could not complete. Please retry the screening.');setBusy(false)}}},1700*(stages.length+1)));return()=>{cancelled=true;ids.forEach(clearTimeout)}},[attempt]);return <section className={`analysis-screen ${stage===stages.length?'resolved':''}`}><div className="analysis-head"><span className="eyebrow">SCREENING PIPELINE · SIMULATION MODE</span><h2>Reviewing retinal images</h2><p>{patient.name} · {single?'single-eye assessment':'both eyes'} · Illustrative demo analysis</p></div><div className="analysis-main"><div className="analysis-retina"><img className="analysis-upload" src={imageSource||DEFAULT_FUNDUS_IMAGE} alt="Retinal image used for this screening"/><div className="analysis-image-overlay"><div className="lesion-mask"/><span className="spatial-marker m1"/><span className="spatial-marker m2"/><span className="analysis-scan"/></div><span className="image-label">{stage>1?'ENHANCED VIEW · DEMO':'ORIGINAL IMAGE · DEMO'}</span></div><div className="stage-list">{stages.map((label,i)=><div key={label} className={stage>i?'stage complete':stage===i?'stage active':'stage'}><span>{stage>i?<Check/>:`0${i+1}`}</span>{label}{stage===i&&<i className="pulse-dot"/>}</div>)}</div></div><div className="evidence-row"><div className={stage>2?'evidence visible':'evidence'}><Eye/><b>Image quality</b><small>Quality step shown · no score stored</small></div><div className={stage>4?'evidence visible':'evidence'}><Activity/><b>Spatial features</b><small>Illustrative feature overlay</small></div><div className={stage>5?'evidence visible':'evidence'}><ShieldCheck/><b>Explainability</b><small>Review cues for specialist</small></div></div><div className="analysis-finish" aria-live="polite"><span>{stage===stages.length&&!busy?<Check/>:<i className="pulse-dot"/>}</span><div><b>{error|| (stage===stages.length?'Resolving screening outcome':'Analysis stages in progress')}</b><small>{error?'Return to image capture and submit again.':'Simulation mode · result is saved once for this screening case'}</small></div>{error&&<button className="button secondary" onClick={()=>{setError('');setBusy(false);setStage(0);setAttempt(value=>value+1)}}>Retry analysis</button>}</div><p className="disclaimer">Demonstration pipeline only · Randomized outcome is not a clinical finding or model performance claim.</p></section>}
function Result({patient,caseData,single,availableEye,onDone}:{patient:Patient;caseData:Case|null;single:boolean;availableEye:'Right eye'|'Left eye';onDone:()=>void}){const {state}=useDemo();const [explanation,setExplanation]=useState(false);const c=caseData,status=c?.aiResult?.status,completed=c?.reviewStatus==='COMPLETED';const positive=status==='POSITIVE'||status==='HIGH_CONFIDENCE_POSITIVE';const negative=status==='NEGATIVE'||status==='HIGH_CONFIDENCE_NEGATIVE'||status==='CONFIDENT';const needsReview=!completed&&(positive||status==='NEEDS_SPECIALIST_REVIEW'||c?.reviewStatus==='REVIEW_REQUIRED');const outcomeState=positive?'HIGH-CONFIDENCE POSITIVE':negative?'HIGH-CONFIDENCE NEGATIVE':'REVIEW NEEDED';const confidence=status==='HIGH_CONFIDENCE_POSITIVE'||status==='HIGH_CONFIDENCE_NEGATIVE'||status==='CONFIDENT'?'High':'Not provided';const isSingle=single||Boolean(c?.eye.toLowerCase().includes('unavailable'));const recordedEye=c?.eye.toLowerCase().includes('left eye available')?'Left eye':c?.eye.toLowerCase().includes('right eye available')?'Right eye':availableEye;const findings=c?.aiResult?.evidence||[];const summary=positive?'Positive screening outcome.':negative?'No significant DR findings were detected.':'Specialist review is recommended.';return <section className="result-wrap"><div className="result-card"><div className="result-symbol"><ShieldCheck/></div><span className="eyebrow">SCREENING RESULT · {c?.aiResult?.source==='SIMULATED_AI'?'SIMULATION MODE':'DEMO CASE'}</span><h1>{outcomeState}</h1><div className="confidence-badge"><span>CONFIDENCE</span><b>{confidence}</b></div><p className="result-lead">{summary}</p>{positive&&findings.length>0&&<section className="result-findings" aria-label="Recorded screening findings"><b>Recorded DR findings</b><ul>{findings.map((finding,i)=><li key={`${i}-${finding}`}>{finding}</li>)}</ul></section>}<p>{positive?'This screening result is a decision-support output and is not a diagnosis.':negative?'This screening result is a decision-support output and is not a diagnosis.':'This case is recommended for ophthalmologist review. The screening result is not a diagnosis.'}</p>{completed&&<div className="review-outcome"><span>DOCTOR REVIEW</span><b>{c?.doctorDecision||'Review completed'}</b>{c?.reviewTimestamp&&<small>{formatReviewDate(c.reviewTimestamp)}</small>}</div>}{isSingle&&<div className="single-eye"><b>SINGLE-EYE ASSESSMENT</b><span>Available eye: {recordedEye}</span><span>Unavailable eye: {recordedEye==='Right eye'?'Left eye':'Right eye'}</span><small>Single-eye evidence is limited and is not equivalent to assessment of both eyes.</small></div>}<div className="result-details"><span>PATIENT <b>{patient.name}</b></span><span>CASE ID <b>{c?.id||'Creating case…'}</b></span><span>STATUS <b>{completed?'REVIEW_COMPLETED':needsReview?'REVIEW_REQUIRED':positive?'POSITIVE':'SCREENING_COMPLETE'}</b></span></div><div className="result-actions">{needsReview&&<Link className="button primary" to="/asha">Forward to specialist <ArrowRight/></Link>}{!needsReview&&<button className="button secondary" onClick={()=>setExplanation(!explanation)}>View explanation <Eye/></button>}<ReportButton caseRecord={c}/><button className="button secondary" onClick={onDone}>Done <Check/></button></div>{explanation&&<p className="explanation-note">{c?.aiResult?.explanation||'No additional explanation was recorded for this case.'}</p>}</div><div className="result-audit"><b>Case activity recorded</b>{state.auditEvents.filter(event=>event.caseId===c?.id).sort((a,b)=>a.timestamp-b.timestamp).slice(-6).map(event=><span key={event.id}><Check/> {event.label}</span>)}{!state.auditEvents.some(event=>event.caseId===c?.id)&&<span>No case activity recorded</span>}</div></section>}
function DoctorOverview(){const {state}=useDemo();const pending=state.cases.filter(c=>c.reviewStatus!=='COMPLETED'&&(c.status==='REVIEW_REQUIRED'||c.status==='Awaiting specialist review'||c.status==='Review required'));const completed=state.cases.filter(c=>c.reviewStatus==='COMPLETED');return <><PageHeader title="Good morning, Doctor" sub="Your specialist review workspace is ready." action={<Link className="button primary" to="/ophthalmologist/queue">Open review queue <ArrowRight size={16}/></Link>}/><div className="metrics"><Metric label="AWAITING REVIEW" value={String(pending.length).padStart(2,'0')} icon={ClipboardCheck} detail="Cases shared by field teams"/><Metric label="REVIEWED CASES" value={String(completed.length).padStart(2,'0')} icon={CheckCircle2} detail="Completed specialist reviews"/><Metric label="AUDIT EVENTS" value={String(state.auditEvents.filter(e=>e.caseId).length).padStart(2,'0')} icon={Activity} detail="Recorded in shared case history"/></div><section className="panel"><div className="panel-head"><div><h2>Priority review queue</h2><p>Cases submitted by ASHA field teams</p></div><Link to="/ophthalmologist/queue">View queue <ArrowRight size={15}/></Link></div><CaseQueueTable cases={pending.slice(0,4)}/></section></>}
function CaseQueueTable({cases:rows}:{cases:Case[]}){const {state}=useDemo();return <div className="table-wrap"><table><thead><tr><th>CASE ID</th><th>PATIENT</th><th>EYE STATUS</th><th>SOURCE PHC</th><th>STATUS</th><th>ACTION</th></tr></thead><tbody>{rows.map(c=>{const p=state.patients.find(x=>x.id===c.patientId);return <tr key={c.id}><td><strong>{c.id}</strong><small>{c.created}</small></td><td><strong>{p?.name||'Unknown patient'}</strong><small>{p?.age} yrs · {p?.village}</small></td><td>{c.eye}</td><td>{c.sourcePhc||'Not recorded'}</td><td><span className={`pill ${c.reviewStatus==='COMPLETED'?'green':c.reviewStatus==='REVIEW_REQUIRED'?'amber':'gray'}`}>{c.reviewStatus==='COMPLETED'?'Completed':c.reviewStatus==='REVIEW_REQUIRED'?'Review required':'Screening complete'}</span></td><td><Link className="table-action" to={`/ophthalmologist/case/${c.id}`}>View case <ArrowRight size={14}/></Link></td></tr>})}</tbody></table>{rows.length===0&&<div className="empty-state"><ClipboardCheck/><b>Queue is clear</b><p>Cases requiring a specialist decision will appear here.</p></div>}</div>}
function ReviewQueue(){const {state}=useDemo();const pending=state.cases.filter(c=>c.reviewStatus!=='COMPLETED'&&(c.status==='REVIEW_REQUIRED'||c.status==='Awaiting specialist review'||c.status==='Review required'));return <><PageHeader title="Review queue" sub="Screening cases shared by the field team for specialist review."/><section className="panel"><div className="panel-head"><div><h2>Needs review</h2><p>{pending.length} case{pending.length===1?'':'s'} awaiting a specialist</p></div><span className="queue-count">{pending.length} OPEN</span></div><CaseQueueTable cases={pending}/></section></>}
function ReviewedCases(){const {state}=useDemo();const done=state.cases.filter(c=>c.reviewStatus==='COMPLETED');return <><PageHeader title="Reviewed cases" sub="Completed specialist reviews from the shared screening workflow."/><section className="panel"><div className="panel-head"><div><h2>Completed reviews</h2><p>{done.length} case{done.length===1?'':'s'} completed</p></div></div><div className="table-wrap"><table><thead><tr><th>CASE ID</th><th>DATE</th><th>REVIEW ACTION</th><th>STATUS</th><th>ACTION</th></tr></thead><tbody>{done.map(c=><tr key={c.id}><td><strong>{c.id}</strong></td><td>{c.reviewTimestamp?new Date(c.reviewTimestamp).toLocaleString():c.created}</td><td>{reviewActionLabel(c.reviewAction)}</td><td><span className="pill green">Completed</span></td><td><Link className="table-action" to={`/ophthalmologist/case/${c.id}`}>Open read-only <ArrowRight size={14}/></Link></td></tr>)}</tbody></table>{done.length===0&&<div className="empty-state"><FileCheck2/><b>No completed reviews yet</b><p>Submitted decisions will be available here.</p></div>}</div></section></>}
function AuditPage(){const {state}=useDemo();const events=[...state.auditEvents].filter(e=>e.caseId).sort((a,b)=>a.timestamp-b.timestamp);return <><PageHeader title="Audit" sub="A case-scoped timeline of screening and specialist activity."/><section className="panel audit-panel"><div className="panel-head"><div><h2>Workflow events</h2><p>Events are read directly from shared demo state</p></div><Activity size={18}/></div>{events.length?events.map((event,i)=><div className="audit-row" key={event.id}><span className={`audit-marker ${event.label==='Decision'?'decision':''}`}>{event.label==='Decision'?<CheckCircle2/>:<Check/>}</span><div className="audit-copy"><b>{event.label}</b><small>{event.caseId} · {event.date}</small></div>{i<events.length-1&&<span className="audit-connector"/>}</div>):<div className="empty-state"><Activity/><b>No audit events</b><p>Case workflow activity will appear here.</p></div>}</section></>}
