 useEffect(()=>{if(current&&state.currentRole==='OPHTHALMOLOGIST')openReviewCase(current.id);setDecision(current?.aiResult?aiResultLabel(current.aiResult.status):current?.aiRecommendation||'Review required');setAction('CONFIRM_AI_RESULT');setNote('');setError('');setConfirm(false);setView('Original');setSelectedEye('Right eye');setZoom(1);setOffset({x:0,y:0})},[caseId]);
if(!current||!patient)return <><PageHeader title="Case unavailable" sub="This case could not be found in the shared demo state."/><Link className="button secondary" to="/ophthalmologist/queue"><ArrowLeft/> Back to queue</Link></>;
const reviewedCase=current!;const completed=reviewedCase.reviewStatus==='COMPLETED';const waitingForReview=reviewedCase.reviewStatus==='REVIEW_REQUIRED'||(!reviewedCase.reviewStatus&&reviewedCase.status==='REVIEW_REQUIRED');const aiResult=reviewedCase.aiResult?aiResultLabel(reviewedCase.aiResult.status):reviewedCase.aiRecommendation||reviewedCase.priority;const selectedSide=selectedEye==='Right eye'?'right':'left';const selectedImage=reviewedCase.imageData?.[selectedSide];const selectedEyeAvailable=reviewedCase.eye.toLowerCase().includes('both')||reviewedCase.eye.toLowerCase().includes(selectedEye.toLowerCase()+' available');function submit(){if(action==='OVERRIDE_AI_RESULT'&&!note.trim()){setError('A reason is required to override the AI recommendation.');setConfirm(false);return}if(submitDoctorReview(reviewedCase.id,action,action==='CONFIRM_AI_RESULT'?aiResult:decision,note)){setConfirm(false);setError('')}}
function pointerDown(e:React.PointerEvent){if(view!=='Original')return;setPan(true);(e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);(e.currentTarget as HTMLElement).dataset.px=String(e.clientX-offset.x);(e.currentTarget as HTMLElement).dataset.py=String(e.clientY-offset.y)}
